import { Order, OrderLine, OrderState } from "../domain/order";
import { OrderRepository, ProductRepository } from "../domain/repositories";
import { OrderDto, PlaceOrderInput } from "./dtos";

export class OrderService {
  public constructor(
    private readonly orders: OrderRepository,
    private readonly products: ProductRepository,
    private readonly createId: () => string = () => crypto.randomUUID(),
  ) {}

  public place(input: PlaceOrderInput): OrderDto {
    const lines = input.items.map((item) => new OrderLine(item.productId, item.quantity));
    const quantities = new Map<string, number>();
    for (const line of lines) quantities.set(line.productId, (quantities.get(line.productId) ?? 0) + line.quantity);

    const products = [...quantities].map(([productId, quantity]) => {
      const product = this.products.findById(productId);
      if (!product) throw new Error(`Product not found: ${productId}`);
      if (product.stock < quantity) throw new Error(`Insufficient stock for product: ${productId}`);
      return { product, quantity };
    });

    const id = input.id ?? this.createId();
    if (this.orders.findById(id)) throw new Error(`Order already exists: ${id}`);
    products.forEach(({ product, quantity }) => product.reserve(quantity));
    const order = new Order(id, lines);
    products.forEach(({ product }) => this.products.save(product));
    this.orders.save(order);
    return this.toDto(order);
  }

  public advance(id: string, state: OrderState): OrderDto {
    const order = this.requireOrder(id);
    order.advanceTo(state);
    this.orders.save(order);
    return this.toDto(order);
  }

  public cancel(id: string): OrderDto {
    const order = this.requireOrder(id);
    order.cancel();
    for (const line of order.lines) {
      const product = this.products.findById(line.productId);
      if (!product) throw new Error(`Product not found: ${line.productId}`);
      product.release(line.quantity);
      this.products.save(product);
    }
    this.orders.save(order);
    return this.toDto(order);
  }

  public list(state?: OrderState): OrderDto[] {
    return this.orders.listByState(state).map((order) => this.toDto(order));
  }

  private requireOrder(id: string): Order {
    const order = this.orders.findById(id);
    if (!order) throw new Error(`Order not found: ${id}`);
    return order;
  }

  private toDto(order: Order): OrderDto {
    return { id: order.id, state: order.state, items: order.lines.map((line) => ({ productId: line.productId, quantity: line.quantity })) };
  }
}

